// One item per pillar keyword. arXiv returns Atom XML in $json.data.
const kw = $('Pillar Keywords').all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const pillar = (kw[i] && kw[i].json.pillar) || 'unknown';
  const raw = items[i].json.data !== undefined ? items[i].json.data : items[i].json;
  const feed = typeof raw === 'string' ? raw : JSON.stringify(raw);
  const entries = feed.match(/<entry>[\s\S]*?<\/entry>/g) || [];
  const rows = entries.map((e) => {
    const id = (e.match(/<id>([^<]+)<\/id>/) || [])[1] || '';
    const title = ((e.match(/<title>([^<]+)<\/title>/) || [])[1] || '').trim();
    const summary = ((e.match(/<summary>([^<]+)<\/summary>/) || [])[1] || '').trim();
    const published = (e.match(/<published>([^<]+)<\/published>/) || [])[1] || '';
    return { node_id: id, kind: 'paper', name: title, pillar, source: 'arxiv', raw_attrs: { summary, published }, ingested_at: new Date().toISOString() };
  });
  const jsonl = rows.map((r) => JSON.stringify(r)).join('\n');
  const binary = await this.helpers.setBinaryDataBuffer(Buffer.from(jsonl, 'utf8'), 'application/x-ndjson');
  out.push({ json: { pillar, count: rows.length, written: jsonl.length }, binary: { data: binary }, pairedItem: { item: i } });
}
return out;

// One item per pillar keyword. HF returns a JSON array as raw text (responseFormat=text
// avoids n8n splitting the array into one item per model).
const kw = $('Pillar Keywords').all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const pillar = (kw[i] && kw[i].json.pillar) || 'unknown';
  const raw = items[i].json.data !== undefined ? items[i].json.data : items[i].json;
  let list = [];
  try {
    const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
    list = Array.isArray(parsed) ? parsed : (Array.isArray(parsed.models) ? parsed.models : []);
  } catch (e) { list = []; }
  const rows = list.map((m) => ({
    node_id: m.id || m.modelId || '',
    kind: 'model',
    name: m.id || m.modelId || '',
    pillar,
    source: 'huggingface',
    raw_attrs: { downloads: m.downloads, likes: m.likes, lastModified: m.lastModified, pipeline_tag: m.pipeline_tag },
    ingested_at: new Date().toISOString()
  }));
  const jsonl = rows.map((r) => JSON.stringify(r)).join('\n');
  const binary = await this.helpers.setBinaryDataBuffer(Buffer.from(jsonl, 'utf8'), 'application/x-ndjson');
  out.push({ json: { pillar, count: rows.length, written: jsonl.length }, binary: { data: binary }, pairedItem: { item: i } });
}
return out;

// One item per package. The HTTP response carries no pillar, so read it from
// the Flatten PyPI Packages node by position.
const src = $('Flatten PyPI Packages').all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const meta = (src[i] && src[i].json) || {};
  const p = items[i].json || {};
  const d = p.data || {};
  const name = p.package || meta.pkg || 'unknown';
  const row = {
