// Validate arXiv — checks the JSONL before it is allowed near the Volume.
// Emits one item per file with ok / errors. Never throws: bad data is data.
const LEG = 'arxiv';
const EXPECTED_KIND = 'paper';
const REQUIRED = ['node_id', 'kind', 'name', 'pillar', 'source'];
const DATE = $now.toFormat('yyyy-MM-dd');
const out = [];
for (let idx = 0; idx < items.length; idx++) {
  const buf = await this.helpers.getBinaryDataBuffer(idx, 'data');
  const lines = buf.toString('utf8').split('\n').filter((l) => l.trim());
  const errors = [];
  const seen = new Set();
  if (lines.length === 0) errors.push('file is empty');
  lines.forEach((l, i) => {
    let r;
    try { r = JSON.parse(l); } catch (e) { errors.push('line ' + (i + 1) + ': invalid JSON'); return; }
    for (const k of REQUIRED) if (!r[k]) errors.push('line ' + (i + 1) + ': missing ' + k);
    if (r.kind && r.kind !== EXPECTED_KIND) errors.push('line ' + (i + 1) + ': kind=' + r.kind + ' expected ' + EXPECTED_KIND);
    if (r.source && r.source !== LEG) errors.push('line ' + (i + 1) + ': source=' + r.source + ' expected ' + LEG);
    if (r.node_id) { if (seen.has(r.node_id)) errors.push('line ' + (i + 1) + ': duplicate node_id ' + r.node_id); seen.add(r.node_id); }
  });
  let first = {};
  try { first = JSON.parse(lines[0] || '{}'); } catch (e) { first = {}; }
  const pillar = first.pillar || 'unknown';
  out.push({
    json: { leg: LEG, pillar, file: pillar + '-' + DATE + '.jsonl', count: lines.length, ok: errors.length === 0, errorCount: errors.length, errors: errors.slice(0, 20) },
    binary: items[idx].binary,
    pairedItem: { item: idx },
  });
}
return out;

