// GATE — single decision point per run.
// ALLOW_PARTIAL = false → any failing leg halts ALL uploads (default).
// ALLOW_PARTIAL = true  → failing legs skipped, healthy legs upload.
const ALLOW_PARTIAL = false;

const all = items.map((i) => i.json);
const bad = all.filter((r) => !r.ok);
const good = all.filter((r) => r.ok);
const blocked = bad.length > 0 && !ALLOW_PARTIAL;

const summary = {
  runAt: new Date().toISOString(),
  totalFiles: all.length,
  okFiles: good.length,
  failedFiles: bad.length,
  allowPartial: ALLOW_PARTIAL,
  blocked,
  legs: all.map((r) => ({
    leg: r.leg,
    pillar: r.pillar,
    file: r.file,
    rows: r.count,
    ok: r.ok,
    errorCount: r.errorCount,
    errors: r.errors,
  })),
};

if (!blocked) {
  return items
    .filter((it) => it.json.ok)
    .map((it) => ({ json: { route: 'upload', ...it.json }, binary: it.binary, pairedItem: it.pairedItem }));
}

// Blocked: ONE item carrying the report plus every healthy payload as a named
// binary, so an approval can still upload them without re-running the legs.
const bin = {};
const manifest = [];
items.forEach((it) => {
  if (!it.json.ok) return;
  const key = 'f' + manifest.length;
  bin[key] = it.binary.data;
  manifest.push({ key, leg: it.json.leg, file: it.json.file, pillar: it.json.pillar, rows: it.json.count });
});
return [{
  json: { route: 'error', reason: 'VALIDATION FAILED — upload halted, awaiting approval', ...summary, manifest },
  binary: bin,
}];

