// Validate PyPI — one file per package, so the filename carries the package name.
const LEG = 'pypi';
const EXPECTED_KIND = 'package';
const REQUIRED = ['node_id', 'kind', 'name', 'pillar', 'source'];
const DATE = $now.toFormat('yyyy-MM-dd');
const out = [];
for (let idx = 0; idx < items.length; idx++) {
  const buf = await this.helpers.getBinaryDataBuffer(idx, 'data');
  const lines = buf.toString('utf8').split('\n').filter((l) => l.trim());
  const errors = [];
  const seen = new Set();
  if (lines.length === 0) errors.push('file is empty');
  lines.forEach((l, i) => {
    let r;
    try { r = JSON.parse(l); } catch (e) { errors.push('line ' + (i + 1) + ': invalid JSON'); return; }
    for (const k of REQUIRED) if (!r[k]) errors.push('line ' + (i + 1) + ': missing ' + k);
    if (r.kind && r.kind !== EXPECTED_KIND) errors.push('line ' + (i + 1) + ': kind=' + r.kind + ' expected ' + EXPECTED_KIND);
    if (r.source && r.source !== LEG) errors.push('line ' + (i + 1) + ': source=' + r.source + ' expected ' + LEG);
    if (r.node_id) { if (seen.has(r.node_id)) errors.push('line ' + (i + 1) + ': duplicate node_id ' + r.node_id); seen.add(r.node_id); }
  });
  let first = {};
  try { first = JSON.parse(lines[0] || '{}'); } catch (e) { first = {}; }
  const pillar = first.pillar || 'unknown';
  const pkg = items[idx].json.pkg || first.node_id || 'unknown';
  out.push({
    json: { leg: LEG, pillar, pkg, file: pillar + '-' + pkg + '-' + DATE + '.jsonl', count: lines.length, ok: errors.length === 0, errorCount: errors.length, errors: errors.slice(0, 20) },
    binary: items[idx].binary,
    pairedItem: { item: idx },
  });
}
return out;

// Validate USPTO — checks the JSONL produced by scripts/uspto_extract.py,
// then passes the file through as binary so the Databricks node can upload it.
// Same contract as every other validator: one item per file, binary attached.
//
// USPTO is UNSCORED (discovery feed) — see pillars_research_11_14_2026.md 6.2.
// It bypasses Gate deliberately, so a USPTO failure can never block uploads of
// healthy legs. It still uploads; it just does not vote on momentum.
const fs = require('fs');
const path = require('path');

const LEG = 'uspto';
const RAW_DIR = 'C:/Users/q1fre/ZED/databricks-app/data/uspto/raw';
const PILLARS = ['self-hosted-vs-saas', 'temporal-memory', 'retrieval-engines', 'data-persistence', 'stack-structure'];

const out = [];

for (let i = 0; i < items.length; i++) {
  const j = items[i].json || {};
  const errors = [];

  // The Execute Command node returns { stdout, stderr, exitCode }.
  const exitCode = j.exitCode;
  if (exitCode !== undefined && exitCode !== 0) {
    errors.push(`extractor exited ${exitCode}`);
  }

  // Locate the JSONL. Prefer the filename echoed by the extractor's stdout.
  const stdout = String(j.stdout || '');
  const m = stdout.match(/wrote \d+ records -> (.+?\.jsonl)/);
  let jsonlPath = m ? m[1].trim() : '';

  if (!jsonlPath) {
    // Fall back to the newest .jsonl in the raw dir.
    try {
      const files = fs.readdirSync(RAW_DIR)
        .filter((f) => f.endsWith('.jsonl'))
        .map((f) => ({ f, t: fs.statSync(path.join(RAW_DIR, f)).mtimeMs }))
        .sort((a, b) => b.t - a.t);
      if (files.length) jsonlPath = path.join(RAW_DIR, files[0].f);
    } catch (e) {
      errors.push(`cannot list ${RAW_DIR}: ${e.message}`);
    }
  }

  let rows = 0;
  let badLines = 0;
  const pillarCounts = {};
  let binary = {};

  if (!jsonlPath) {
    errors.push('no JSONL produced');
  } else if (!fs.existsSync(jsonlPath)) {
    errors.push(`JSONL missing: ${jsonlPath}`);
  } else {
    const buf = fs.readFileSync(jsonlPath);
    const lines = buf.toString('utf8').split('\n').filter((l) => l.trim());
    rows = lines.length;
    for (const line of lines) {
      let rec;
      try {
        rec = JSON.parse(line);
      } catch {
        badLines++;
        continue;
      }
      if (!rec.node_id || !rec.kind || !rec.name || !rec.source) badLines++;
      if (rec.pillar && !PILLARS.includes(rec.pillar)) badLines++;
      if (rec.pillar) pillarCounts[rec.pillar] = (pillarCounts[rec.pillar] || 0) + 1;
    }
    if (badLines > 0) errors.push(`${badLines} malformed line(s)`);
    // Zero matches is a legitimate outcome (quiet day), not a failure.

    // Pass the file through so Databricks can upload it.
    binary = { data: await this.helpers.setBinaryDataBuffer(buf, 'application/x-ndjson') };
  }

  out.push({
    json: {
      leg: LEG,
      pillar: 'multi',
      scored: false,
      role: 'discovery',
      file: jsonlPath ? path.basename(jsonlPath) : 'none',
      count: rows,
      ok: errors.length === 0,
      errorCount: errors.length,
      errors,
      pillarCounts,
      exitCode: exitCode === undefined ? null : exitCode,
    },
    binary,
    pairedItem: { item: i },
  });
}

return out;

// Rebuilds one item per healthy leg from the payloads Gate stashed on the
// blocked item, so an approved run uploads without re-fetching anything.
const gate = $('Gate').first().json;
const bin = $('Gate').first().binary || {};
const out = [];
for (const m of (gate.manifest || [])) {
  if (!bin[m.key]) continue;
  out.push({ json: { leg: m.leg, file: m.file, pillar: m.pillar, rows: m.rows }, binary: { data: bin[m.key] } });
}
return out;

// Detail response: bulkDataProductBag[0].productFileBag.fileDataBag[]
// Real file keys: fileName, fileSize, fileDataFromDate, fileDataToDate,
//                 fileTypeText, fileDownloadURI, fileReleaseDate, fileLastModifiedDateTime
const bag = ($json && Array.isArray($json.bulkDataProductBag)) ? $json.bulkDataProductBag : [];
const prod = bag[0] || {};
const files = (prod.productFileBag && Array.isArray(prod.productFileBag.fileDataBag))
  ? prod.productFileBag.fileDataBag
  : [];
if (!files.length) {
  return [{ json: { ok: false, leg: 'uspto', error: 'no fileDataBag entries' } }];
}

// Newest by data coverage date, then release date, then filename.
const dateOf = (f) => String(
  f.fileDataToDate || f.fileReleaseDate || f.fileLastModifiedDateTime || f.fileName || ''
);
const latest = files.slice().sort((a, b) => dateOf(b).localeCompare(dateOf(a)))[0];
const url = latest.fileDownloadURI || '';
if (!url) {
  return [{ json: { ok: false, leg: 'uspto', error: 'no fileDownloadURI on latest file', sample: latest } }];
}

return [{ json: {
  ok: true,
  leg: 'uspto',
  file: latest.fileName || 'tdxf.zip',
  dataFrom: latest.fileDataFromDate || '',
  dataTo: latest.fileDataToDate || '',
  released: latest.fileReleaseDate || '',
  fileSize: latest.fileSize || 0,
  download_url: url,
} }];

const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const PILLARS = JSON.parse(buf.toString('utf8'));
return PILLARS.map((p) => ({ json: p }));

// One item per pillar keyword. OpenAlex returns { results: [...] }.
const kw = $('Pillar Keywords2').all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const pillar = (kw[i] && kw[i].json.pillar) || 'unknown';
  const j = items[i].json || {};
  const list = Array.isArray(j.results) ? j.results : [];
  const rows = list.map((w) => ({
    node_id: w.id || '',
    kind: 'paper',
    name: (w.title || '').trim(),
    pillar,
    source: 'openalex',
    raw_attrs: { doi: w.doi || '', cited_by_count: w.cited_by_count, publication_year: w.publication_year, authorships: (w.authorships || []).length },
    ingested_at: new Date().toISOString()
  }));
  const jsonl = rows.map((r) => JSON.stringify(r)).join('\n');
  const binary = await this.helpers.setBinaryDataBuffer(Buffer.from(jsonl, 'utf8'), 'application/x-ndjson');
  out.push({ json: { pillar, count: rows.length, written: jsonl.length }, binary: { data: binary }, pairedItem: { item: i } });
}
return out;

// npm bulk lookups reject scoped packages (@scope/name), so split the cohort:
//   unscoped -> ONE bulk range call (up to 128 packages)
//   scoped   -> one call each, spaced
// Emits one item per REQUEST, not per package. Parse npm Stats fans the
// response back out to one row per package.
const out = [];
const unscoped = [];
const scoped = [];

for (const item of items) {
  const p = item.json || {};
  for (const pkg of (p.npm || [])) {
    const entry = { pillar: p.pillar, keyword: p.keyword, pkg };
    if (pkg.startsWith('@')) scoped.push(entry);
    else unscoped.push(entry);
  }
}

if (unscoped.length) {
  out.push({
    json: {
      mode: 'bulk',
      pkgs: unscoped.map((e) => e.pkg),
      path: unscoped.map((e) => e.pkg).join(','),
      meta: unscoped,
    },
  });
}

for (const entry of scoped) {
  out.push({
    json: { mode: 'single', pkgs: [entry.pkg], path: encodeURIComponent(entry.pkg), meta: [entry] },
  });
}

return out;

// npm returns a top-level object keyed by package name.
//   bulk   -> { "n8n": {...}, "openclaw": {...} }
//   single -> { "downloads": [...], "package": "...", "start": ..., "end": ... }
// Normalise both into one row per package, then emit one JSONL file each.
const src = $('Flatten npm Packages').all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const req = (src[i] && src[i].json) || {};
  const meta = req.meta || [];
  const resp = items[i].json || {};

  // Single-package responses are not keyed by name; wrap them.
  const byPkg = resp.package ? { [resp.package]: resp } : resp;

  for (const entry of meta) {
    const p = byPkg[entry.pkg];
    if (!p) continue;
    const days = Array.isArray(p.downloads) ? p.downloads : [];

    // Isolated zeros are gaps in npm's data, not real zero-download days.
    const values = days.map((d) => Number(d.downloads) || 0);
    const total = values.reduce((a, b) => a + b, 0);
    const nonZero = values.filter((v) => v > 0);

    const row = {
      node_id: 'npm:' + entry.pkg,
      kind: 'package',
      name: entry.pkg,
      pillar: entry.pillar || 'unknown',
      source: 'npm',
      raw_attrs: {
        registry: 'npm',
        window_start: p.start || null,
        window_end: p.end || null,
        days: days.length,
        total_7d: total,
        last_day: values.length ? values[values.length - 1] : 0,
        zero_days: values.length - nonZero.length,
        series: days.map((d) => ({ day: d.day, downloads: Number(d.downloads) || 0 })),
      },
      ingested_at: new Date().toISOString(),
    };
    const jsonl = JSON.stringify(row);
    const binary = await this.helpers.setBinaryDataBuffer(Buffer.from(jsonl, 'utf8'), 'application/x-ndjson');
    out.push({
      json: { pillar: row.pillar, pkg: entry.pkg, count: 1, days: days.length, total_7d: total, written: jsonl.length },
      binary: { data: binary },
      pairedItem: { item: i },
    });
  }
}
return out;

// Validate npm — one file per package, so the filename carries the package name.
// Scoped names (@scope/name) must be sanitised the SAME way as Write npm JSONL,
// because the Databricks node builds its upload path from this `file` field.
const LEG = 'npm';
const EXPECTED_KIND = 'package';
const REQUIRED = ['node_id', 'kind', 'name', 'pillar', 'source'];
const DATE = $now.toFormat('yyyy-MM-dd');
const out = [];
for (let idx = 0; idx < items.length; idx++) {
  const buf = await this.helpers.getBinaryDataBuffer(idx, 'data');
  const lines = buf.toString('utf8').split('\n').filter((l) => l.trim());
  const errors = [];
  const seen = new Set();
  if (lines.length === 0) errors.push('file is empty');
  lines.forEach((l, i) => {
    let r;
    try { r = JSON.parse(l); } catch (e) { errors.push('line ' + (i + 1) + ': invalid JSON'); return; }
    for (const k of REQUIRED) if (!r[k]) errors.push('line ' + (i + 1) + ': missing ' + k);
    if (r.kind && r.kind !== EXPECTED_KIND) errors.push('line ' + (i + 1) + ': kind=' + r.kind + ' expected ' + EXPECTED_KIND);
    if (r.source && r.source !== LEG) errors.push('line ' + (i + 1) + ': source=' + r.source + ' expected ' + LEG);
    if (r.node_id) { if (seen.has(r.node_id)) errors.push('line ' + (i + 1) + ': duplicate node_id ' + r.node_id); seen.add(r.node_id); }
  });
  let first = {};
  try { first = JSON.parse(lines[0] || '{}'); } catch (e) { first = {}; }
  const pillar = first.pillar || 'unknown';
  const pkg = items[idx].json.pkg || first.node_id || 'unknown';
  const safe = String(pkg).replace(/[@\/]/g, '');
  out.push({
    json: { leg: LEG, pillar, pkg, file: pillar + '-' + safe + '-' + DATE + '.jsonl', count: lines.length, ok: errors.length === 0, errorCount: errors.length, errors: errors.slice(0, 20) },
    binary: items[idx].binary,
    pairedItem: { item: idx },
  });
}
return out;

// TEST ONLY — deliberately FAILING gate payload so Route takes the error branch.
// Shape matches real Gate output: route, leg, pillar, file, count, ok, errorCount, errors[]
// No binary on purpose: the Slack/approve leg only reads file + count.
return [{
