    route: 'upload',
    leg: 'arxiv',
    pillar: 'self-hosted-vs-saas',
    file: 'TEST-forced-failure-2026-11-16.jsonl',
    count: 3,
    ok: false,
    errorCount: 1,
    errors: ['TEST: forced failure to exercise Slack approve leg'],
  },
}];
